"""Regenerate the pinned CPython 3.12 Unicode scalar lowercase data.

Run with CPython 3.12 (Unicode 15) from any directory. This reads only built-in
Unicode tables and writes src/python_lowercase.rs plus PYTHON_LOWERCASE.json.
The generated data is used only by the opt-in Python backreference instruction.
"""
import _sre
import hashlib
import json
import platform
import sys
import unicodedata
from pathlib import Path

assert platform.python_implementation() == "CPython"
assert sys.version_info[:2] == (3, 12)
assert unicodedata.unidata_version == "15.0.0"
root = Path(__file__).resolve().parent.parent
pairs = [(code, _sre.unicode_tolower(code)) for code in range(0x110000)
         if not 0xD800 <= code <= 0xDFFF and _sre.unicode_tolower(code) != code]
assert len(pairs) == 1433
assert hashlib.sha256(json.dumps(pairs, separators=(",", ":")).encode()).hexdigest() == "9c194d67a570656df4baba4ab72b80eafcbf3f2f4ff4594de9b908f48e6430ed"
ranges = []
index = 0
while index < len(pairs):
    start, lower = pairs[index]
    end, delta, step = start, lower - start, 1
    if (index + 1 < len(pairs)
            and pairs[index + 1][1] - pairs[index + 1][0] == delta
            and pairs[index + 1][0] - start in (1, 2)):
        step = pairs[index + 1][0] - start
        while (index + 1 < len(pairs) and pairs[index + 1][0] - end == step
               and pairs[index + 1][1] - pairs[index + 1][0] == delta):
            index += 1
            end = pairs[index][0]
    ranges.append((start, end, step, delta))
    index += 1
assert len(ranges) == 182
assert {code: code + delta for start, end, step, delta in ranges
        for code in range(start, end + 1, step)} == dict(pairs)
source = '''// Generated by tools/generate_python_lowercase.py from CPython 3.12, Unicode 15.
// See PYTHON_LOWERCASE.json for provenance and LICENSE-CPYTHON for source terms.
// Single-scalar lowercase is intentionally different from Unicode simple folding.

pub(crate) fn lowercase(value: char) -> char {
    let code = value as u32;
    let index = LOWERCASE.partition_point(|&(_, end, _, _)| end < code);
    let Some(&(start, _, step, delta)) = LOWERCASE.get(index) else {
        return value;
    };
    if start <= code && (code - start) % step == 0 {
        char::from_u32((i64::from(code) + i64::from(delta)) as u32)
            .expect("verified Unicode lowercase table")
    } else {
        value
    }
}

// Inclusive start/end, input stride, signed lowercase delta. Identity is omitted.
const LOWERCASE: &[(u32, u32, u32, i32)] = &[
'''
source += "".join(f"    (0x{start:x}, 0x{end:x}, {step}, {delta}),\n"
                  for start, end, step, delta in ranges)
source += "];\n"
(root / "src/python_lowercase.rs").write_text(source)
(root / "PYTHON_LOWERCASE.json").write_text(json.dumps({
    "source": "CPython 3.12.14 _sre.unicode_tolower",
    "unicode_version": "15.0.0",
    "source_urls": [
        "https://github.com/python/cpython/blob/v3.12.14/Modules/_sre/sre.c",
        "https://github.com/python/cpython/blob/v3.12.14/Objects/unicodectype.c",
        "https://github.com/python/cpython/blob/v3.12.14/Objects/unicodetype_db.h",
    ],
    "source_license_file": "LICENSE-CPYTHON",
    "generator_python": platform.python_version(),
    "nonidentity_mappings": len(pairs),
    "strided_delta_ranges": len(ranges),
    "canonical_pairs_json_sha256": hashlib.sha256(
        json.dumps(pairs, separators=(",", ":")).encode()).hexdigest(),
    "generated_source_sha256": hashlib.sha256(source.encode()).hexdigest(),
}, indent=2) + "\n")
